<?php $step=(int)$tenant['onboarding_step'];$percent=(int)round($step/9*100);?><div class="row justify-content-center"><div class="col-lg-8"><div class="d-flex justify-content-between"><h1 class="h3">Configure sua agenda</h1><strong><?=$step?>/9 — <?=$percent?>%</strong></div><div class="progress mb-4"><div class="progress-bar" style="width:<?=$percent?>%"></div></div><div class="card border-0 shadow-sm"><div class="card-body p-4"><form method="post" action="/onboarding"><?=\App\Core\CSRF::field()?><input type="hidden" name="step" value="<?=$step?>"><?php if($step===1):?><h2 class="h5">Empresa</h2><input class="form-control mb-2" name="name" value="<?=htmlspecialchars($tenant['name'],ENT_QUOTES,'UTF-8')?>" required><textarea class="form-control" name="description" placeholder="Descrição"></textarea><?php elseif($step===2):?><h2 class="h5">Identidade visual</h2><input class="form-control form-control-color" type="color" name="primary_color" value="<?=htmlspecialchars($tenant['primary_color'],ENT_QUOTES,'UTF-8')?>"><?php elseif($step===3):?><h2 class="h5">Unidade</h2><input class="form-control mb-2" name="unit_name" placeholder="Nome da unidade" required><input class="form-control" name="address" placeholder="Endereço"><?php elseif($step===4):?><h2 class="h5">Primeiro profissional</h2><input class="form-control" name="professional_name" required><?php elseif($step===5):?><h2 class="h5">Primeiro serviço</h2><input class="form-control mb-2" name="service_name" required><div class="row"><div class="col"><input class="form-control" name="duration" type="number" value="30" min="5"></div><div class="col"><input class="form-control" name="price" type="number" step=".01" min="0"></div></div><?php elseif($step===6):?><h2 class="h5">Agenda do primeiro profissional</h2><p class="text-secondary">Defina quando <?=htmlspecialchars($professional['name']??'o profissional',ENT_QUOTES,'UTF-8')?> atende. Esses horários alimentarão a página pública.</p><?php $av=[];foreach(($availability??[]) as $r)$av[(int)$r['weekday']]=$r;$days=[1=>'Segunda',2=>'Terça',3=>'Quarta',4=>'Quinta',5=>'Sexta',6=>'Sábado',7=>'Domingo'];foreach($days as $i=>$label):$r=$av[$i]??null;$enabled=$r?(bool)$r['active']:($i<=6);?><div class="row g-2 align-items-center border-bottom py-2"><div class="col-md-3"><label class="form-check"><input class="form-check-input" type="checkbox" name="day_<?=$i?>" value="1" <?=$enabled?'checked':''?>> <?=$label?></label></div><div class="col"><input class="form-control" type="time" name="start_<?=$i?>" value="<?=htmlspecialchars(substr((string)($r['start_time']??'09:00'),0,5))?>"></div><div class="col"><input class="form-control" type="time" name="end_<?=$i?>" value="<?=htmlspecialchars(substr((string)($r['end_time']??($i===6?'14:00':'18:00')),0,5))?>"></div></div><?php endforeach;?><?php elseif($step===7):?><h2 class="h5">Página pública</h2><p>Seu link público de agendamento será <code>/a/<?=htmlspecialchars($tenant['public_short_code']??$tenant['public_slug']??'',ENT_QUOTES,'UTF-8')?></code>.</p><?php elseif($step===8):?><h2 class="h5">Comunicação automática</h2><p>Os lembretes e campanhas automáticas por e-mail/WhatsApp são administrados centralmente pela plataforma. Você não precisa cadastrar credenciais técnicas.</p><?php else:?><h2 class="h5">Publicar</h2><div class="form-check"><input class="form-check-input" type="checkbox" name="terms" id="terms" required><label class="form-check-label" for="terms">Li e aceito os <a href="/termos" target="_blank">Termos de Uso</a> (versão <?=htmlspecialchars($legal['terms']['version']??'vigente')?>) e a <a href="/privacidade" target="_blank">Política de Privacidade</a> (versão <?=htmlspecialchars($legal['privacy']['version']??'vigente')?>)</label></div><?php endif;?><button class="btn btn-primary mt-4"><?=$step===9?'Concluir e publicar':'Continuar'?></button></form><?php if($step===9):?><a class="btn btn-success mt-4 ms-2" href="/a/<?=htmlspecialchars($tenant['public_short_code']??$tenant['public_slug']??'',ENT_QUOTES,'UTF-8')?>">Ver agenda pública</a><?php endif;?></div></div></div></div>
